import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { gunzipSync } from 'node:zlib';

const directory = '/private/tmp/jobs53-negation-extended-UxgquY';
const sourceRoot = '/private/tmp/safe-bash-gnu-5.3-adjudication.0zMRKT';
const archivePath = `${sourceRoot}/bash-5.3.tar.gz`;
const archiveSHA256 = '0d5cd86965f869a26cf64f4b71be7b96f90a3ba8b3d74e27e8e9d9d5550f31ba';
const names = ['execute_cmd.c', 'jobs.c', 'builtins/wait.def', 'command.h', 'parse.y'];
const identityKeys = ['dev', 'ino', 'size', 'mode', 'mtimeMs', 'ctimeMs'];
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const save = (name, value) => fs.writeFileSync(`${directory}/${name}`, JSON.stringify(value, null, 2) + '\n', { flag: 'wx' });

function admit(path, maximum, expected) {
  assert.equal(fs.realpathSync(path), path);
  const before = fs.lstatSync(path);
  assert.ok(before.isFile() && !before.isSymbolicLink() && before.size <= maximum);
  const handle = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  try {
    const held = fs.fstatSync(handle);
    for (const key of identityKeys) assert.equal(held[key], before[key]);
    const bytes = Buffer.alloc(before.size);
    let total = 0;
    while (total < bytes.length) {
      const count = fs.readSync(handle, bytes, total, bytes.length - total, null);
      assert.ok(count > 0, 'input shrank');
      total += count;
    }
    assert.equal(fs.readSync(handle, Buffer.alloc(1), 0, 1, null), 0, 'input grew');
    for (const after of [fs.fstatSync(handle), fs.lstatSync(path)]) for (const key of identityKeys) assert.equal(after[key], before[key], 'input identity drift');
    const sha256 = digest(bytes);
    if (expected) assert.equal(sha256, expected);
    return { bytes, record: { path, sha256, ...Object.fromEntries(identityKeys.map(key => [key, before[key]])) } };
  } finally { fs.closeSync(handle); }
}

function field(bytes) {
  const end = bytes.indexOf(0);
  return bytes.subarray(0, end < 0 ? bytes.length : end).toString('ascii');
}

function octal(bytes) {
  const value = field(bytes).trim();
  assert.ok(value.length > 0 && [...value].every(character => character >= '0' && character <= '7'));
  const result = Number.parseInt(value, 8);
  assert.ok(Number.isSafeInteger(result) && result >= 0);
  return result;
}

try {
  save('source-audit-startup.json', { time: new Date().toISOString(), task: 'pinned local source-only extended negation, pipeline, function, and exit completion audit', nativeLaunches: 0, compressedMaximumBytes: 16777216, inflatedMaximumBytes: 67108864, selectedFileMaximumBytes: 1048576 });
  const archive = admit(archivePath, 16777216, archiveSHA256);
  const inflated = gunzipSync(archive.bytes, { maxOutputLength: 67108864 });
  assert.equal(inflated.length, 37934080);
  const selected = new Map();
  let offset = 0;
  let headers = 0;
  while (offset + 512 <= inflated.length) {
    const header = inflated.subarray(offset, offset + 512);
    if (header.every(byte => byte === 0)) break;
    assert.ok(++headers <= 20000);
    const expected = octal(header.subarray(148, 156));
    let checksum = 0;
    for (let index = 0; index < 512; index++) checksum += index >= 148 && index < 156 ? 32 : header[index];
    assert.equal(checksum, expected);
    const size = octal(header.subarray(124, 136));
    const name = field(header.subarray(0, 100));
    const prefix = field(header.subarray(345, 500));
    const complete = prefix ? `${prefix}/${name}` : name;
    const start = offset + 512;
    assert.ok(start + size <= inflated.length);
    for (const requested of names) if (complete === `bash-5.3/${requested}`) {
      assert.ok(header[156] === 0 || header[156] === 48, 'selected archive entry not regular');
      assert.ok(!selected.has(requested) && size <= 1048576);
      selected.set(requested, Buffer.from(inflated.subarray(start, start + size)));
    }
    offset = start + Math.ceil(size / 512) * 512;
  }
  assert.equal(selected.size, names.length);
  const sources = {};
  const matches = {};
  for (const name of names) {
    const native = admit(`${sourceRoot}/bash-5.3/${name}`, 1048576);
    assert.ok(native.bytes.equals(selected.get(name)), 'source differs from pinned archive');
    sources[name] = { ...native.record, archiveMemberSHA256: digest(selected.get(name)), matchesArchive: true };
    const text = new TextDecoder('utf-8', { fatal: true }).decode(native.bytes);
    const lines = text.split('\n');
    const needles = name === 'execute_cmd.c' ? ['CMD_INVERT_RETURN', 'subshell_exit', 'asynchronous', 'wait_for_single_pid'] : name === 'jobs.c' ? ['process_exit_status', 'wait_for_single_pid', 'last_command_exit_value', 'raw_job_exit_status'] : name === 'builtins/wait.def' ? ['wait_for_single_pid', 'WAIT_RETURN', 'EXECUTION_FAILURE'] : name === 'parse.y' ? ['CMD_INVERT_RETURN', 'BANG pipeline_command'] : ['CMD_INVERT_RETURN'];
    matches[name] = lines.flatMap((line, index) => needles.some(needle => line.includes(needle)) ? [{ line: index + 1, text: line }] : []);
  }
  const archiveAfter = admit(archivePath, 16777216, archiveSHA256);
  assert.deepEqual(archiveAfter.record, archive.record);
  for (const name of names) assert.deepEqual(admit(sources[name].path, 1048576, sources[name].sha256).record, Object.fromEntries(Object.entries(sources[name]).filter(([key]) => key !== 'archiveMemberSHA256' && key !== 'matchesArchive')));
  save('source-authentication.json', { time: new Date().toISOString(), archive: archive.record, uncompressedBytes: inflated.length, headersVisited: headers, sources, sourceMatches: matches, nativeLaunches: 0, qualification: 'Exact recorded local archive and selected source bytes authenticated before/after; no fresh upstream signature verification or source-to-pinned-binary reproducibility claim.' });
  for (const [name, records] of Object.entries(matches)) console.log(JSON.stringify({ name, sha256: sources[name].sha256, matches: records }));
} catch (reason) {
  save('source-audit-failure.json', { time: new Date().toISOString(), reason: String(reason), stack: reason.stack, nativeLaunches: 0 });
  console.error(reason);
  process.exitCode = 1;
}

