  for (const [name, path] of Object.entries(paths)) {
    assert.equal(seal.bindings[name].path, path);
    const admitted = admittedFile(path, limits[name], name === 'subjects' || name === 'supervisor', retainedHandles);
    assert.equal(admitted.record.sha256, seal.bindings[name].sha256, `${name} seal mismatch`);
    result[name] = admitted;
  }
  assert.equal(result.bash.record.sha256, expectedBash);
  assert.equal(result.node.record.sha256, expectedNode);
  assert.equal(result.supervisor.record.sha256, expectedWrapper);
