    const result = await runCase(entry, admitted.supervisor.bytes.toString('utf8'), recordsOnly(admitted));
    const after = authenticate(seal);
    save(`case-${entry.id}-authentication-after.json`, recordsOnly(after));
    assert.deepEqual(recordsOnly(after), recordsOnly(before), 'postlaunch identity drift');
    results.push(result);
    if (result.failure || !result.cleanupComplete || result.deadlineExceeded) {
      save('incomplete.json', { results, stoppedWithoutRetry: true, noLaterCase: true });
      throw new Error(`case ${entry.id} did not qualify; no retries or later launches`);
    }
  }
  const after = authenticate(seal);
  for (const retained of retainedHandles) {
    const current = fs.fstatSync(retained.handle);
    for (const key of identityKeys) assert.equal(current[key], retained.before[key], `final retained ${retained.path} ${key} drift`);
  }
  assert.deepEqual(recordsOnly(after), recordsOnly(before));
  save('inventory-after.json', recordsOnly(after));
  save('results.json', { results, nativeQualificationOnly: true, originSubjects: 4, originSupervisors: 4, candidateSubjects: 10, candidateSupervisors: 10, observedSupervisors: results.filter(entry => entry.supervisorPid !== undefined).length, observedSubjectAnnouncements: results.filter(entry => entry.subject !== undefined).length, structuralMaximumSimultaneousBashProcesses: 4, subjectStatusCounts: results.reduce((counts, entry) => ({ ...counts, [entry.subjectStatus]: (counts[entry.subjectStatus] ?? 0) + 1 }), {}), classification: 'ten exact extended negation-boundary observations; no expected-status goldens or product-pass assertions', retries: 0 });
  console.log(JSON.stringify({ directory, cases: results.length, status: results.map(entry => entry.status), cleanupComplete: results.every(entry => entry.cleanupComplete), retries: 0 }));
} catch (reason) {
  try { save('fatal.json', { time: new Date().toISOString(), reason: describe(reason), noRetriesOrLaterLaunches: true }); }
  catch (publicationFailure) { console.error('Fatal evidence publication failed', publicationFailure); }
  console.error(reason);
  process.exitCode = 1;
} finally {
  for (const retained of retainedHandles) {
    try { fs.closeSync(retained.handle); }
    catch (reason) { console.error('Retained input close failed', reason); process.exitCode = 1; }
  }
}

