      "startLine": 1764,
      "endLine": 1788,
      "text": "      dispose_redirects (command->redirects);
      command->redirects = (REDIRECT *)NULL;
#if 1
#if defined (PROCESS_SUBSTITUTION) && defined (JOB_CONTROL)
      if (user_subshell && command->type == cm_subshell)
	procsub_clear ();
#endif
#endif
    }

